// Built by script: the HTML parser stops nesting at 512 levels, so only script can go deeper.
const depth = Number(new URLSearchParams(location.search).get('depth') ?? 5000);
let node = document.getElementById('deep');
for (let i = 0; i < depth; i++) {
  const div = document.createElement('div');
  div.style.margin = '0';
  node.append(div);
  node = div;
}
const button = document.createElement('button');
button.type = 'button';
button.id = 'bottom';
button.textContent = 'Bottom button';
node.append(button);
document.title = `Deep nesting (${depth})`;
